import {movementAt} from './world-model.js';
export function editFootprint(api,o){
 const $=s=>document.querySelector(s),w=o.w,h=o.h;if(!Number.isInteger(w)||!Number.isInteger(h)||w>32||h>32){api.toast('Use whole tile sizes up to 32 × 32 for a fitted mask, or paint tile overrides with Collision → Paint.');return;}
 let colour=1;const map=api.map(),isolated={...map,objects:[o],markers:[],fieldObjects:[],gates:[],wallCells:[],movement:[]},mask=Array.from({length:h},(_,y)=>Array.from({length:w},(_,x)=>{if(o.collisionChoice==='mask'){const v=o.collisionMask?.[y]?.[x]??null;return v===0&&o.collisionMaskVersion!==2&&o.building&&y<h-1?2:v;}const r=movementAt(isolated,Math.floor(o.x)+x,Math.floor(o.y)+y);return r.collision?1:r.behind?2:0;}));
 api.modal('Footprint · '+(o.name||'Object'),`<p>Paint this object's own mask. It moves with the object. Purple upper artwork draws in front of the player.</p><div class="studio-actions">${[[1,'Blocked'],[2,'Walk behind'],[0,'Walkable'],['null','Keep terrain']].map(([v,n])=>`<button type="button" data-mask-colour="${v}">${n}</button>`).join('')}</div><div id="objectMask" class="collision-mask-grid" style="grid-template-columns:repeat(${w},minmax(28px,1fr))"></div><p class="hint-line">Red: blocked · purple: walk behind · green: walkable · grey: preserve terrain. Tile overrides painted on the map take precedence.</p>`,()=>{api.change(()=>{o.collisionChoice='mask';o.collisionMask=mask;o.collisionMaskVersion=2;});api.refresh();},'Save footprint');
 function draw(){const target=$('#objectMask');target.innerHTML=mask.map((row,y)=>row.map((v,x)=>`<button data-mask-cell="${x},${y}" data-mask-value="${v}" type="button" aria-label="Tile ${x},${y}: ${v===1?'blocked':v===2?'walk behind':v===0?'walkable':'keep terrain'}">${v===null?'·':v}</button>`).join('')).join('');let drawing=false;const paint=b=>{if(!b||!target.contains(b))return;const [x,y]=b.dataset.maskCell.split(',').map(Number);mask[y][x]=colour;b.dataset.maskValue=String(colour);b.textContent=colour===null?'·':colour;b.setAttribute('aria-label',`Tile ${x},${y}: ${colour===1?'blocked':colour===2?'walk behind':colour===0?'walkable':'keep terrain'}`);};target.querySelectorAll('[data-mask-cell]').forEach(b=>b.onclick=()=>paint(b));target.addEventListener('pointerdown',e=>{const cell=e.target.closest('[data-mask-cell]');if(!cell)return;e.preventDefault();drawing=true;target.setPointerCapture?.(e.pointerId);paint(cell);});target.addEventListener('pointermove',e=>{if(drawing)paint(document.elementFromPoint?.(e.clientX,e.clientY)?.closest('[data-mask-cell]'));});target.addEventListener('pointerup',()=>drawing=false);target.addEventListener('pointercancel',()=>drawing=false);}
 document.querySelectorAll('[data-mask-colour]').forEach(b=>b.onclick=()=>{colour=b.dataset.maskColour==='null'?null:+b.dataset.maskColour;document.querySelectorAll('[data-mask-colour]').forEach(v=>v.classList.toggle('active',v===b));});draw();
}
